def can_finish(n, edges):
    # Repeatedly remove nodes with indegree 0 (slow O(n^2) scans)
    remaining = set(range(n))
    preds = {i: set() for i in range(n)}
    for a, b in edges:
        preds[a].add(b)
    while remaining:
        ready = [u for u in remaining if preds[u].isdisjoint(remaining)]
        if not ready:
            return False
        for u in ready:
            remaining.remove(u)
    return True
